<script setup>
import I from './Icon.vue';
import CoverRange from './CoverRange.vue';
import CoverColor from './CoverColor.vue';
const props=defineProps({modelValue:Object,fonts:Array,bounds:Object});const emit=defineEmits(['update:modelValue']);
function set(path,value){const next=JSON.parse(JSON.stringify(props.modelValue)),keys=path.split('.');let target=next;for(const key of keys.slice(0,-1))target=target[key];target[keys.at(-1)]=value;emit('update:modelValue',next);}
function font(event){const item=props.fonts.find(f=>f.id===event.target.value);if(item){const next={...props.modelValue,fontId:item.id,fontFamily:item.family};emit('update:modelValue',next);}}
const flags=[['bold','粗体','Bold'],['italic','斜体','Italic'],['underline','下划线','Underline']];
const alignments=[['left','左对齐','AlignLeft'],['center','居中对齐','AlignCenter'],['right','右对齐','AlignRight']];
</script>
<template><div class="cover-text-properties cover-property-card">
  <h4>基础设置</h4>
  <div class="cover-font-row"><label><span>字体类型</span><select :value="modelValue.fontId||fonts.find(f=>f.family===modelValue.fontFamily||f.label===modelValue.fontFamily)?.id||''" aria-label="封面字体" @change="font"><option value="" disabled>{{modelValue.fontFamily}}</option><option v-for="font in fonts" :key="font.id" :value="font.id">{{font.label}}</option></select></label><CoverRange label="字号" :model-value="modelValue.fontSize" :min="8" :max="600" @update:model-value="set('fontSize',$event)"/></div>
  <div class="cover-property-grid"><div class="cover-toggle-row"><span>样式</span><div role="group" aria-label="文字样式"><button v-for="[key,label,icon] in flags" :key="key" :aria-label="label" :aria-pressed="modelValue[key]" :class="{active:modelValue[key]}" @click="set(key,!modelValue[key])"><I :name="icon" :size="15"/></button></div></div><div class="cover-toggle-row"><span>对齐</span><div role="group" aria-label="文字对齐"><button v-for="[value,label,icon] in alignments" :key="value" :aria-label="label" :aria-pressed="modelValue.align===value" :class="{active:modelValue.align===value}" @click="set('align',value)"><I :name="icon" :size="15"/></button></div></div>
  <CoverColor label="文字颜色" :model-value="modelValue.color" @update:model-value="set('color',$event)"/><CoverRange label="透明度" :model-value="Math.round(modelValue.opacity*100)" :max="100" suffix="%" @update:model-value="set('opacity',$event/100)"/>
  <CoverRange label="字间距" :model-value="modelValue.letterSpacing" :min="-10" :max="80" @update:model-value="set('letterSpacing',$event)"/><CoverRange label="行间距" :model-value="modelValue.lineHeight" :min="0.5" :max="3" :step="0.05" @update:model-value="set('lineHeight',$event)"/></div>
  <div class="cover-position-grid"><label v-for="[key,label,min,max] in [['x','位置 X',-1080,2160],['y','位置 Y',-1920,3840],['rotation','旋转角',-180,180]]" :key="key">{{label}}<input type="number" :aria-label="label" :value="modelValue[key]" :min="min" :max="max" @change="$event.target.value!==''&&set(key,Math.max(min,Math.min(max,Number($event.target.value))))"/></label></div>
  <section><h4><label><span>描边</span><input type="checkbox" aria-label="文字描边" :checked="modelValue.stroke.enabled" @change="set('stroke.enabled',$event.target.checked)"/></label></h4><div v-if="modelValue.stroke.enabled" class="cover-property-grid"><CoverColor label="描边颜色" :model-value="modelValue.stroke.color" @update:model-value="set('stroke.color',$event)"/><CoverRange label="描边粗细" :model-value="modelValue.stroke.width" :max="40" @update:model-value="set('stroke.width',$event)"/></div></section>
  <section><h4><label><span>背景</span><input type="checkbox" aria-label="文字背景" :checked="modelValue.background.enabled" @change="set('background.enabled',$event.target.checked)"/></label></h4><template v-if="modelValue.background.enabled"><div class="cover-property-grid"><CoverColor label="背景颜色" :model-value="modelValue.background.color" @update:model-value="set('background.color',$event)"/><CoverRange label="背景透明度" :model-value="Math.round(modelValue.background.opacity*100)" :max="100" suffix="%" @update:model-value="set('background.opacity',$event/100)"/></div><CoverRange label="背景圆角" :model-value="modelValue.background.radius" :max="200" @update:model-value="set('background.radius',$event)"/><CoverRange label="背景宽度" :model-value="modelValue.background.width??Math.round((bounds?.width||modelValue.boxWidth)+32)" :min="20" :max="2200" @update:model-value="set('background.width',$event)"/><CoverRange label="背景高度" :model-value="modelValue.background.height??Math.round((bounds?.height||modelValue.fontSize)+20)" :min="20" :max="2000" @update:model-value="set('background.height',$event)"/><button class="text-button" @click="set('background',{...modelValue.background,width:null,height:null})">背景自适应文字</button></template></section>
  <section><h4><label><span>阴影</span><input type="checkbox" aria-label="文字阴影" :checked="modelValue.shadow.enabled" @change="set('shadow.enabled',$event.target.checked)"/></label></h4><div v-if="modelValue.shadow.enabled" class="cover-property-grid"><CoverColor label="阴影颜色" :model-value="modelValue.shadow.color" @update:model-value="set('shadow.color',$event)"/><CoverRange label="阴影透明度" :model-value="Math.round(modelValue.shadow.opacity*100)" :max="100" suffix="%" @update:model-value="set('shadow.opacity',$event/100)"/><CoverRange label="阴影模糊度" :model-value="modelValue.shadow.blur" :max="80" @update:model-value="set('shadow.blur',$event)"/><CoverRange label="阴影距离" :model-value="modelValue.shadow.distance" :min="-100" :max="100" @update:model-value="set('shadow.distance',$event)"/></div></section>
</div></template>
